import os,re,json,itertools
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m.group(2)),int(m.group(3))
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); T=G['Test input']
ops={'hv':lambda r,c:[(r,23-c),(23-r,c),(23-r,23-c)],'hv+t':lambda r,c:[(r,23-c),(23-r,c),(23-r,23-c),(c,r)],
     'hv+ad':lambda r,c:[(r,23-c),(23-r,c),(23-r,23-c),(23-c,23-r)]}
def solve(I,fn):
    H=len(I);W=24;out=[r[:] for r in I];ch=True
    while ch:
        ch=False
        for r in range(H):
            for c in range(W):
                if out[r][c]!=2: continue
                vals=set()
                for rr,cc in fn(r,c):
                    if 0<=rr<H and 0<=cc<W and out[rr][cc]!=2: vals.add(out[rr][cc])
                if len(vals)==1: out[r][c]=vals.pop();ch=True;break
    return out
